const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location - Hotan area in Taklamakan Desert
  const hotan = ee.Geometry.Point([79.9, 37.1]);
  const roi = hotan.buffer(50000); // 50km radius

  // 2. Define dates
  const date1Start = '2020-02-20';
  const date1End = '2020-02-26';
  const date2Start = '2020-04-26';
  const date2End = '2020-05-02';

  // 3. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 5. Acquire February data
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(roi)
    .filterDate(date1Start, date1End)
    .map(maskS2clouds)
    .map(addNDVI);

  const size1 = col1.size().getInfo();
  console.log(`February 2020 Images: ${size1}`);

  if (size1 === 0) {
    // Try Landsat 8 as fallback
    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date1Start, date1End);
    const size1_l8 = col1.size().getInfo();
    console.log(`February 2020 Landsat Images: ${size1_l8}`);
    if (size1_l8 === 0) {
      console.log('No data for February 2020.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 6. Acquire April data
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(roi)
    .filterDate(date2Start, date2End)
    .map(maskS2clouds)
    .map(addNDVI);

  const size2 = col2.size().getInfo();
  console.log(`April 2020 Images: ${size2}`);

  if (size2 === 0) {
    // Try Landsat 8 as fallback
    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date2Start, date2End);
    const size2_l8 = col2.size().getInfo();
    console.log(`April 2020 Landsat Images: ${size2_l8}`);
    if (size2_l8 === 0) {
      console.log('No data for April 2020.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 7. Create median composites
  const img1 = col1.median();
  const img2 = col2.median();

  // 8. Check pixel counts
  const count1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`February valid pixels: ${count1}`);
  console.log(`April valid pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Calculate mean NDVI
  const ndvi1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`February NDVI: ${ndvi1}`);
  console.log(`April NDVI: ${ndvi2}`);

  // 10. Validation and final answer
  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2)) {
    console.log('Invalid NDVI calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (ndvi1 < -1 || ndvi1 > 1 || ndvi2 < -1 || ndvi2 > 1) {
    console.log('NDVI out of valid range.');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = ndvi2 - ndvi1;
  console.log(`NDVI Change: ${change.toFixed(4)}`);

  if (change > 0) {
    console.log('Vegetation cover increased.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation cover did not increase.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
